const fs = require('fs');
const wb = JSON.parse(fs.readFileSync('watchbill.json','utf8'));
const refs = Object.values(wb).flatMap(w => w.scenarios);
console.log('Watchbill references:', refs.length);

// Check each reference exists in the feature files
const allFeatures = {};
fs.readdirSync('features').filter(f => f.endsWith('.feature')).forEach(f => {
  const content = fs.readFileSync('features/' + f, 'utf8');
  const scenarios = content.match(/Scenario:\s*(.+)/g) || [];
  allFeatures['features/' + f] = scenarios.map(s => s.replace(/Scenario:\s*/, '').trim());
});

let missing = 0;
refs.forEach(ref => {
  const [file, name] = ref.split(':');
  if (!allFeatures[file]) { console.log('Missing file:', file); missing++; return; }
  if (!allFeatures[file].includes(name)) { console.log('Missing scenario:', ref); missing++; }
});
if (missing === 0) console.log('All watchbill references valid');
"
